import { useVehicle } from '@/app/axios';
import { useEffect } from 'react';
import { useTranslations } from 'next-intl';

const CarFilter = () => {
  const t = useTranslations('carFilter');
  const { filterMetadata, fetchFilterMetadata, isLoading, error, clearError } = useVehicle();

  useEffect(() => {
    fetchFilterMetadata();
  }, [fetchFilterMetadata]);

  useEffect(() => {
    if (error) {
      const timer = setTimeout(clearError, 5000);
      return () => clearTimeout(timer);
    }
  }, [error, clearError]);

  if (isLoading) {
    return (
      <div className="p-3 md:p-4">
        <div className="animate-pulse">
          <div className="mb-2 h-3 w-3/4 rounded bg-gray-200 md:h-4"></div>
          <div className="mb-2 h-3 w-1/2 rounded bg-gray-200 md:h-4"></div>
          <div className="h-3 w-2/3 rounded bg-gray-200 md:h-4"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded border border-red-200 bg-red-50 p-3 md:p-4">
        <p className="text-xs text-red-700 md:text-sm">
          {t('error')}: {error}
        </p>
        <button
          onClick={() => {
            clearError();
            fetchFilterMetadata();
          }}
          className="mt-2 rounded bg-red-600 px-3 py-1 text-xs text-white hover:bg-red-700 md:text-sm"
        >
          {t('retry')}
        </button>
      </div>
    );
  }

  if (!filterMetadata) {
    return <div className="p-4 text-gray-500">{t('noData')}</div>;
  }

  return (
    <div className="w-full bg-white p-4">
      <h3 className="mb-4 text-xl font-bold">{t('exploreFleet')}</h3>

      {/* Body Types Filter */}
      {filterMetadata.bodyTypes && filterMetadata.bodyTypes.length > 0 && (
        <div className="mb-6">
          <h4 className="mb-2 font-bold">{t('byBodyTypes')}</h4>
          <Accordion type="multiple" className="w-full">
            {filterMetadata.bodyTypes.map((bodyType) => (
              <AccordionItem key={bodyType.bodyType} value={bodyType.bodyType} className="border-none">
                <AccordionTrigger className="py-2 hover:no-underline [&[data-state=open]>svg]:rotate-0">
                  <div className="flex items-center gap-2">
                    <div className="relative flex h-4 w-4 items-center justify-center rounded-[2px] bg-[#3B82F6] text-white">
                      <Plus className="absolute h-3 w-3 transition-transform duration-200 group-data-[state=open]:scale-0 group-data-[state=open]:rotate-90" />
                      <Minus className="absolute h-3 w-3 scale-0 transition-transform duration-200 group-data-[state=open]:scale-100" />
                    </div>
                    <span className="text-base font-normal text-gray-700">{bodyType.bodyType}</span>
                  </div>
                  <span className="ml-auto text-sm text-gray-500">[{bodyType.count}]</span>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="pt-2 pl-6 text-sm text-gray-500">
                    {/* Placeholder for models */}
                    <p className="py-1">Model A</p>
                    <p className="py-1">Model B</p>
                  </div>
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      )}

      {/* Brands Filter */}
      {filterMetadata.brands && filterMetadata.brands.length > 0 && (
        <div className="mb-6">
          <h4 className="mb-2 font-bold">{t('byBrands')}</h4>
          <Accordion type="multiple" className="w-full">
            {filterMetadata.brands.map((brand) => (
              <AccordionItem key={brand.make} value={brand.make} className="border-none">
                <AccordionTrigger className="py-2 hover:no-underline [&[data-state=open]>svg]:rotate-0">
                  <div className="flex items-center gap-2">
                    <div className="relative flex h-4 w-4 items-center justify-center rounded-[2px] bg-[#3B82F6] text-white">
                      <Plus className="absolute h-3 w-3 transition-transform duration-200 group-data-[state=open]:scale-0 group-data-[state=open]:rotate-90" />
                      <Minus className="absolute h-3 w-3 scale-0 transition-transform duration-200 group-data-[state=open]:scale-100" />
                    </div>
                    <span className="text-base font-normal text-gray-700">{brand.make}</span>
                  </div>
                  <span className="ml-auto text-sm text-gray-500">[{brand.count}]</span>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="pt-2 pl-6 text-sm text-gray-500">
                    {/* Placeholder for models */}
                    <p className="py-1">Model X</p>
                    <p className="py-1">Model Y</p>
                  </div>
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      )}
    </div>
  );
};

export default CarFilter;
